<template><div class="space-y-4 p-4"><div v-if="item" class="m-card"><p class="text-[10px] uppercase tracking-wider text-indigo-500">Supplier listing</p><h1 class="mt-2 text-xl font-bold text-slate-800">{{ item.title }}</h1><p class="mt-4 text-2xl font-bold text-indigo-600">{{ money(item.price_minor, item.currency) }}</p><NuxtLink to="/buyer/post-request" class="m-btn-primary mt-5 block text-center">Request this solution</NuxtLink></div><p v-if="error" class="m-card text-sm text-red-600">{{ error }}</p></div></template>
<script setup lang="ts">
const route = useRoute(); const { getPublicListing } = useCommerce(); const item = ref<any>(); const error = ref(''); const money = (value?: number, currency = 'EUR') => value == null ? 'Request price' : new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(value / 100); onMounted(async () => { try { item.value = await getPublicListing(String(route.params.id)) } catch (e: any) { error.value = e?.data?.detail || e?.message } })
</script>
